<?php $pageTitle=$pageTitle??'Form';$row=is_array($row??null)?$row:[];$categories=isset($this->categories)&&is_array($this->categories)?$this->categories:[];$suppliers=isset($this->suppliers)&&is_array($this->suppliers)?$this->suppliers:[];$isEdit=isset($row['id'])&&$row['id']!=='';require __DIR__.'/../partials/header.php';require __DIR__.'/../partials/sidebar.php';?><main class="main"><div class="container-fluid"><?php require __DIR__.'/../partials/navbar.php';?><div class="card-shell form-card"><form method="post" enctype="multipart/form-data" action="?page=<?=e($this->view)?>/<?=$isEdit?'update':'store'?>"><?php if($isEdit):?><input type="hidden" name="id" value="<?=e($row['id'])?>"><?php endif;?><?php foreach($this->fields as $k=>$label):?><label><?=e($k==='kategori_id'?'Kategori':($k==='supplier_id'?'Supplier':$label))?></label><?php if($k==='kode'):?><input class="form-control mb-3" name="kode" value="<?=e($row[$k]??'')?>" readonly><?php elseif($k==='role'||$k==='status'): $choices=$k==='role'?['admin'=>'Admin','kasir'=>'Kasir']:['aktif'=>'Aktif','nonaktif'=>'Nonaktif'];?><select class="form-select mb-3" name="<?=e($k)?>" required><?php foreach($choices as $value=>$text):?><option value="<?=$value?>" <?=$value===($row[$k]??'')?'selected':''?>><?=$text?></option><?php endforeach;?></select><?php elseif($k==='kategori_id'||$k==='supplier_id'):$list=$k==='kategori_id'?$categories:$suppliers;?><select class="form-select mb-3" name="<?=e($k)?>" required><option value="">Pilih <?=e($k==='kategori_id'?'kategori':'supplier')?></option><?php foreach($list as $option):?><option value="<?=e($option['id'])?>" <?=($option['id']??null)==($row[$k]??null)?'selected':''?>><?=e($option['nama']??'')?></option><?php endforeach;?></select><?php elseif($k==='harga'):?><div class="input-group mb-3"><span class="input-group-text">Rp</span><input class="form-control" type="number" min="0" name="harga" value="<?=e($row['harga']??'')?>" required></div><?php else:?><input class="form-control mb-3" name="<?=e($k)?>" value="<?=e($row[$k]??'')?>" required><?php endif;?><?php endforeach;?><?php if($this->view==='users'&&!$isEdit):?><label>Password</label><input class="form-control mb-3" type="password" name="password" minlength="6" required><small class="text-muted d-block mb-3">Minimal 6 karakter.</small><?php endif;?><?php if($this->view==='produk'):?><label>Gambar produk</label><input class="form-control mb-2" type="file" name="gambar" accept="image/jpeg,image/png,image/webp"><small class="text-muted d-block mb-3">JPG, PNG, atau WebP. Maksimal 2 MB.</small><?php endif;?><a href="?page=<?=e($this->view)?>" class="btn btn-light">Batal</a> <button class="btn btn-primary">Simpan</button></form></div></div><?php require __DIR__.'/../partials/footer.php';?>
